// data.ts

export type QuestionType = 
  | "reading" 
  | "vocabulary" 
  | "grammar" 
  | "tashkeel" 
  | "orthography" 
  | "grammar_advanced"
  | "listening"       
  | "grammar_basic"
  | "reorder"; // ★ 追加: 並び替え問題用のタイプ

export type QuizQuestion = {
  id?: number; 
  type: QuestionType;
  text: string;
  
  // ★ 変更: 並び替え問題では使わないため、オプショナル（?）に変更しておくと今後のデータ作成が楽になります
  options?: string[];
  correctIndex?: number;
  
  explanation: string;
  audio?: string; 
  relatedGrammarId?: number; 

  // ★★★ 追加: 並び替え問題専用のプロパティ（オプショナル） ★★★
  correctOrder?: string[]; // 正解の単語の並び（例: ["أنا", "طالب", "جديد"]）
  acceptableOrders?: string[][]; // ★ ここを追加: 複数正解のパターン配列
  distractors?: string[];  // ダミーの単語（例: ["مدرسة", "في"]）
};

export type Vocab = {
  word: string;
  meaning: string;
};

export type KeyExpression = {
  phrase: string;
  explanation: string;
  reading?: string; 
};

export type Sentence = {
  arabic: string;
  japanese: string;
  speaker?: string; 
  note?: string;    
  // ★★★ 追加: 関連する文法記事のID（オプショナル） ★★★
  relatedGrammarId?: number;
};

export type Article = {
  id: number;
  title: string;
  category: string;
  // ★ "1フレーズ" を追加
  level: "初級" | "会話" | "中級" | "上級" | "文法" | "Poetry" | "1フレーズ"; 
  
  contentVoweled: string;
  contentPlain: string;
  
  vocabList: Vocab[];
  questions: QuizQuestion[];
  sentences: Sentence[]; 
  
  keyExpressions?: KeyExpression[];

  videoUrl?: string;     
  imageUrls?: string[];  
};

